import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  世界: z.object({
    当前日期: z.string().prefault(''),
    当前时间: z.string().prefault(''),
    当前地点: z.string().prefault(''),
  }),

  晴可: z.object({
    好感度: z.coerce.number().transform(v => _.clamp(v, 0, 200)).prefault(0),
    表白状态: z.coerce.number().transform(v => v >= 1 ? 1 : 0).prefault(0),
    爱恋状态: z.coerce.number().transform(v => v >= 1 ? 1 : 0).prefault(0),
  }),
});

$(() => {
  registerMvuSchema(Schema);
})

