    /* [修复] 封装头图切换逻辑，确保 position 在图片加载完成后仍然生效 */
    function updateHeaderImage(phase) {
      var $headerImg = $('#header-img');
      var currentSrc = $headerImg.attr('src');

      /* 先设置 position，再判断是否需要换 src */
      $headerImg.css('object-position', phase.position);

      if (currentSrc !== phase.url) {
        /* 换图：先解绑旧的 load 事件，绑定新的，确保新图加载完成后 position 不丢 */
        $headerImg.off('load.phasefix');
        $headerImg.on('load.phasefix', function() {
          $(this).css('object-position', phase.position);
        });
        $headerImg.attr('src', phase.url);
      }
    }

